<?php require_once __DIR__.'/config/database.php';require_once __DIR__.'/config/auth.php';require_page('reports.php');$role=current_role();$data=[];$rows=[];$title='';$desc='';
if($role==='management'){$data=[['Registered Patients',(int)$pdo->query('SELECT COUNT(*) FROM patients')->fetchColumn(),'Master patient index'],['Appointments',(int)$pdo->query('SELECT COUNT(*) FROM appointments')->fetchColumn(),'Operational schedule'],['Clinical Encounters',(int)$pdo->query('SELECT COUNT(*) FROM encounters')->fetchColumn(),'Clinical workload'],['Collected Revenue',(float)$pdo->query('SELECT COALESCE(SUM(amount),0) FROM payments')->fetchColumn(),'Finance KPI']];$rows=$pdo->query("SELECT DATE(appointment_date) tanggal,COUNT(*) jumlah FROM appointments GROUP BY DATE(appointment_date) ORDER BY tanggal DESC LIMIT 14")->fetchAll();$title='Executive Operations';$desc='Aggregate KPI tanpa membuka isi rekam medis individual.';}
elseif($role==='doctor'){$d=doctor_id($pdo);$data=[['My Encounters',(int)$pdo->query("SELECT COUNT(*) FROM encounters WHERE doctor_id=$d")->fetchColumn(),'Patient encounters'],['Unsigned SOAP',(int)$pdo->query("SELECT COUNT(*) FROM encounters WHERE doctor_id=$d AND clinical_status='draft'")->fetchColumn(),'Needs finalization'],['My Orders',(int)$pdo->query("SELECT COUNT(*) FROM cpoe_orders WHERE ordered_by=".current_user_id())->fetchColumn(),'CPOE workload'],['My Prescriptions',(int)$pdo->query("SELECT COUNT(*) FROM prescriptions WHERE doctor_id=$d")->fetchColumn(),'E-prescribing']];$rows=$pdo->prepare("SELECT clinical_status,COUNT(*) jumlah FROM encounters WHERE doctor_id=? GROUP BY clinical_status ORDER BY clinical_status");$rows->execute([$d]);$rows=$rows->fetchAll();$title='Clinical Productivity';$desc='KPI dokter hanya untuk patient care yang menjadi tanggung jawabnya.';}
elseif($role==='nurse'){$data=[['Nursing Notes',(int)$pdo->query("SELECT COUNT(*) FROM nursing_notes WHERE nurse_id=".current_user_id())->fetchColumn(),'My documentation'],['Vital Signs',(int)$pdo->query("SELECT COUNT(*) FROM vital_signs WHERE recorded_by=".current_user_id())->fetchColumn(),'My observations'],['High Fall Risk',(int)$pdo->query("SELECT COUNT(*) FROM nursing_notes WHERE nurse_id=".current_user_id()." AND fall_risk='high'")->fetchColumn(),'Requires attention'],['Appointments Today',(int)$pdo->query("SELECT COUNT(*) FROM appointments WHERE DATE(appointment_date)=CURDATE() AND status NOT IN ('cancelled','no_show')")->fetchColumn(),'Unit workload']];$rows=$pdo->query("SELECT DATE(recorded_at) tanggal,COUNT(*) jumlah FROM nursing_notes GROUP BY DATE(recorded_at) ORDER BY tanggal DESC LIMIT 14")->fetchAll();$title='Nursing Operations';$desc='Ringkasan aktivitas keperawatan, bukan editing clinical notes.';}
elseif($role==='pharmacist'){$data=[['Active Medicines',(int)$pdo->query('SELECT COUNT(*) FROM medicines WHERE is_active=1')->fetchColumn(),'Inventory'],['Low Stock',(int)$pdo->query('SELECT COUNT(*) FROM medicines WHERE is_active=1 AND stock<=min_stock')->fetchColumn(),'Restock'],['Pending Rx',(int)$pdo->query("SELECT COUNT(*) FROM prescriptions WHERE status='pending'")->fetchColumn(),'Verification'],['Dispensed Rx',(int)$pdo->query("SELECT COUNT(*) FROM prescriptions WHERE status='dispensed'")->fetchColumn(),'Completed']];$rows=$pdo->query("SELECT status,COUNT(*) jumlah FROM prescriptions GROUP BY status ORDER BY jumlah DESC")->fetchAll();$title='Pharmacy KPI';$desc='Inventory dan medication workflow.';}
elseif($role==='laboratory'){$data=[['Lab Orders',(int)$pdo->query("SELECT COUNT(*) FROM cpoe_orders WHERE order_type='laboratory'")->fetchColumn(),'Worklist'],['Released Results',(int)$pdo->query('SELECT COUNT(*) FROM lab_results WHERE reported_at IS NOT NULL')->fetchColumn(),'Verified'],['Critical Results',(int)$pdo->query("SELECT COUNT(*) FROM lab_results WHERE flag='critical'")->fetchColumn(),'Escalation'],['Open Orders',(int)$pdo->query("SELECT COUNT(*) FROM cpoe_orders WHERE order_type='laboratory' AND status<>'completed'")->fetchColumn(),'Pending']];$rows=$pdo->query("SELECT DATE(o.ordered_at) tanggal,COUNT(*) jumlah FROM cpoe_orders o WHERE o.order_type='laboratory' GROUP BY DATE(o.ordered_at) ORDER BY tanggal DESC LIMIT 14")->fetchAll();$title='Laboratory KPI';$desc='Workload laboratorium dan release result.';}
elseif($role==='radiology'){$data=[['Imaging Orders',(int)$pdo->query("SELECT COUNT(*) FROM cpoe_orders WHERE order_type='radiology'")->fetchColumn(),'Worklist'],['Reports Released',(int)$pdo->query('SELECT COUNT(*) FROM radiology_results WHERE reported_at IS NOT NULL')->fetchColumn(),'Final reports'],['Urgent Orders',(int)$pdo->query("SELECT COUNT(*) FROM cpoe_orders WHERE order_type='radiology' AND priority='urgent'")->fetchColumn(),'Priority'],['Open Orders',(int)$pdo->query("SELECT COUNT(*) FROM cpoe_orders WHERE order_type='radiology' AND status<>'completed'")->fetchColumn(),'Pending']];$rows=$pdo->query("SELECT DATE(o.ordered_at) tanggal,COUNT(*) jumlah FROM cpoe_orders o WHERE o.order_type='radiology' GROUP BY DATE(o.ordered_at) ORDER BY tanggal DESC LIMIT 14")->fetchAll();$title='Radiology KPI';$desc='Imaging workload dan reporting.';}
elseif($role==='cashier'){$data=[['Invoices',(int)$pdo->query('SELECT COUNT(*) FROM invoices')->fetchColumn(),'Billing'],['Unpaid',(int)$pdo->query("SELECT COUNT(*) FROM invoices WHERE status IN ('unpaid','partial')")->fetchColumn(),'Follow-up'],['Paid',(int)$pdo->query("SELECT COUNT(*) FROM invoices WHERE status='paid'")->fetchColumn(),'Completed'],['Collected',(float)$pdo->query('SELECT COALESCE(SUM(amount),0) FROM payments')->fetchColumn(),'Payment']];$rows=$pdo->query("SELECT DATE(paid_at) tanggal,SUM(amount) total,COUNT(*) transaksi FROM payments GROUP BY DATE(paid_at) ORDER BY tanggal DESC LIMIT 14")->fetchAll();$title='Revenue Cycle';$desc='Finance-only operational reporting.';}
elseif($role==='registration'){$data=[['Patients',(int)$pdo->query('SELECT COUNT(*) FROM patients')->fetchColumn(),'MPI'],['Episodes',(int)$pdo->query('SELECT COUNT(*) FROM registrations')->fetchColumn(),'Registration'],['Queued',(int)$pdo->query("SELECT COUNT(*) FROM registrations WHERE status='queued'")->fetchColumn(),'Queue'],['Today Appointments',(int)$pdo->query('SELECT COUNT(*) FROM appointments WHERE DATE(appointment_date)=CURDATE()')->fetchColumn(),'Scheduling']];$rows=$pdo->query("SELECT status,COUNT(*) jumlah FROM registrations GROUP BY status ORDER BY jumlah DESC")->fetchAll();$title='Front Office KPI';$desc='Operational registration data only.';}
else{$data=[['Clinical Encounters',(int)$pdo->query('SELECT COUNT(*) FROM encounters')->fetchColumn(),'Record completeness'],['Signed SOAP',(int)$pdo->query("SELECT COUNT(*) FROM encounters WHERE clinical_status IN ('signed','amended')")->fetchColumn(),'Finalized'],['Nursing Notes',(int)$pdo->query('SELECT COUNT(*) FROM nursing_notes')->fetchColumn(),'Documentation'],['Orders',(int)$pdo->query('SELECT COUNT(*) FROM cpoe_orders')->fetchColumn(),'Clinical orders']];$rows=$pdo->query("SELECT clinical_status,COUNT(*) jumlah FROM encounters GROUP BY clinical_status")->fetchAll();$title='Medical Record Quality';$desc='Kelengkapan dokumentasi untuk Rekam Medis; tidak ada editing klinis.';}
$page_title='Laporan & KPI';$page_subtitle=$desc;include __DIR__.'/includes/header.php';?><div class="grid cards"><?php foreach($data as $d):?><div class="card stat"><div class="icon">▥</div><div class="num"><?=is_float($d[1])?'Rp '.number_format($d[1],0,',','.'):number_format($d[1])?></div><div class="label"><?=h($d[0])?></div><div class="hint"><?=h($d[2])?></div></div><?php endforeach;?></div><div class="card" style="margin-top:18px"><div class="card-header"><div><h3 class="section-title"><?=h($title)?></h3><p class="section-subtitle">Laporan dibatasi pada fungsi role dan tidak menjadi pintu masuk ke seluruh rekam medis.</p></div></div><div class="table-wrap"><table><tr><th>Dimensi</th><th>Jumlah</th><?php if(!in_array($role,['pharmacist','registration','doctor','medical_record'],true)):?><th>Total</th><?php endif;?></tr><?php foreach($rows as $r):?><tr><td><?=h($r['tanggal']??($r['status']??'—'))?></td><td><?=h((string)$r['jumlah'])?></td><?php if(!in_array($role,['pharmacist','registration','doctor','medical_record'],true)):?><td><?=isset($r['total'])?'Rp '.number_format($r['total'],0,',','.'):h((string)($r['transaksi']??'—'))?></td><?php endif;?></tr><?php endforeach;?></table></div></div><?php include __DIR__.'/includes/footer.php';?>